}

function onOut(S, mod, out, ctx, eff) {
  if (!out) return;
  if (mod === 'intake') return recorded(S, out, ctx, eff);
  if (mod === 'review') return reviewed(S, out, ctx, eff);
  if (mod === 'window') return windowed(S, out, ctx, eff);
